                    sidebarTab === 'journey'
                      ? 'border-amber-500 text-amber-600 bg-white'
                      : 'border-transparent text-slate-500 hover:text-slate-800 hover:bg-slate-100/50'
                  }`}
                >
                  <Clock className="w-4 h-4" />
                  <span>JOURNEY / CRM</span>
                </button>
                <button
                  type="button"
                  onClick={() => setSidebarTab('pmax')}
