import { CaseRow, DerivedFlags, DashboardKpis, DashboardCharts } from '../types';
export function getTodayStart(): Date { const today = new Date('2026-06-05T00:00:00Z'); // Matches current time in metadata today.setHours(0, 0, 0, 0); return today; }
export function parseDateSafe(value: string): Date | null { if (!value) return null; const date = new Date(value); if (isNaN(date.getTime())) return null; return date; }
export function splitTasks(value: string): string[] { return String(value || '') .split(/\n|,/) .map(task => task.replace(/^\d+\.\s*/, '').trim()) .filter(Boolean); }
export function groupCount(rows: CaseRow[], key: keyof CaseRow): Record<string, number> { const result: Record<string, number> = {}; rows.forEach(row => { const rawVal = row[key]; const value = String(rawVal === undefined || rawVal === null || rawVal === '' ? 'Blank' : rawVal); result[value] = (result[value] || 0) + 1; }); return result; }
export function groupMultiCount(rows: CaseRow[], key: 'taskBucket'): Record<string, number> { const result: Record<string, number> = {}; rows.forEach(row => { const rawValue = row[key]; if (!rawValue) { result.Blank = (result.Blank || 0) + 1; return; } splitTasks(rawValue).forEach(task => { result[task] = (result[task] || 0) + 1; }); }); return result; }
export function topN(objectValue: Record<string, number>, limit: number): Record<string, number> { const result: Record<string, number> = {}; Object.entries(objectValue) .sort((a, b) => b[1] - a[1]) .slice(0, limit) .forEach(([key, value]) => { result[key] = value; }); return result; }
export function average(values: number[]): number { const validValues = values.filter(v => !isNaN(v) && v > 0); if (!validValues.length) return 0; const sum = validValues.reduce((a, b) => a + b, 0); return sum / validValues.length; }
export function getDerivedFlags(row: CaseRow): DerivedFlags { const today = getTodayStart(); const leadStage = String(row.leadStage || '').trim(); const dealStatus = String(row.dealStatus || '').trim(); const taskBucket = String(row.taskBucket || '').toLowerCase(); const paymentType = String(row.paymentType || '').toLowerCase(); const expectedDeliveryDate = row.expectedDeliveryDate; const actualDeliveryDate = row.actualDeliveryDate; const lastCallAt = row.lastCallAt; const paymentPercentage = Number(row.paymentPercentage || 0); const amountPending = Number(row.amountPending || 0); const amountCollected = Number(row.amountCollected || 0); const isAlertVisible = String(row.isAlertVisible || '').toLowerCase(); const onDemandStatus = row.onDemandStatus;
const isCancelledCase = leadStage === 'CANCELLED' || dealStatus === 'CANCEL';
let isEddBreached = false; if (expectedDeliveryDate && !actualDeliveryDate) { const edd = parseDateSafe(expectedDeliveryDate); if (edd) { edd.setHours(0, 0, 0, 0); isEddBreached = edd.getTime() < today.getTime(); } }
let isCustomerConnectPending = taskBucket.includes('customer connect'); if (!isCustomerConnectPending && lastCallAt) { const lastCallDate = parseDateSafe(lastCallAt); if (lastCallDate) { const diffDays = (today.getTime() - lastCallDate.getTime()) / (1000 * 60 * 60 * 24); isCustomerConnectPending = diffDays > 2; } }
if (!lastCallAt && leadStage === 'ACTIVE_TOKEN') { isCustomerConnectPending = true; }
