export function buildKpis(rows: CaseRow[]): DashboardKpis { const flagsList = rows.map(r => getDerivedFlags(r));
const totalCollected = rows.reduce((sum, r) => sum + Number(r.amountCollected || 0), 0); const totalPending = rows.reduce((sum, r) => sum + Number(r.amountPending || 0), 0);
const bookingsWithTasks = rows.filter(r => splitTasks(r.taskBucket).length > 0).length; const totalTaskInstances = rows.reduce((sum, r) => sum + splitTasks(r.taskBucket).length, 0);
return { totalCases: rows.length, activeTokens: flagsList.filter(f => f.isActiveToken).length, delivered: flagsList.filter(f => f.isDelivered).length, cancelled: flagsList.filter(f => f.isCancelled).length, bookingsWithTasks, totalTaskInstances, pmaxCases: flagsList.filter(f => f.isPmaxCase).length, paymentPending: flagsList.filter(f => f.isPaymentPending).length, totalCollected, totalPending, avgPaymentPercentage: average(rows.map(r => Number(r.paymentPercentage || 0))) }; }
export function buildDerivedStatusCount(rows: CaseRow[]): Record<string, number> { const result = { 'Alert Cases': 0, 'EDD Missing': 0, 'EDD Breached': 0, 'PMax Stuck': 0, 'Customer Connect Pending': 0, 'High Payment Pending Delivery': 0, 'Cancelled After Payment': 0, 'OD Pending': 0, 'Blank Payment Type': 0, 'Payment Pending': 0 };
